/* Design-only fixture interactions. No API, database, credentials or persistent storage. */
const app=document.querySelector('#app'), sheet=document.querySelector('#sheet');
const params=new URLSearchParams(location.search); if(params.has('clean'))document.body.classList.add('clean'); if(params.has('capture'))document.body.classList.add('capture');
let luisPaid=8000, luisDelivered=false, productionStarted=false;
let viewState=params.get('state')||'default', factor='2', customer='Ana', delivered=false, amountPaid=24000, toastTimer;
let selectedIngredient=0, recipeIngredients=[['Harina de trigo','500','g','$21.00'],['Mantequilla','100','g','$30.00'],['Azúcar','100','g','$4.00'],['Leche','200','ml','$5.00'],['Canela','10','g','$10.00'],['Levadura','10','g','$10.00']], currentPrice=4000, pendingPrice=4000;
const drafts={}, money=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:2}).format(n/100), short=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n/100);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<span class="icon ${cls}" style="--icon:url('../icons/${name}.svg')" aria-hidden="true"></span>`;
const btn=(text,action,style='',ic='')=>`<button type="button" class="button ${style}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const link=(text,route,style='',ic='')=>`<a class="button ${style}" href="#${route}">${ic?icon(ic):''}${text}</a>`;
const brand=()=>`<div class="brand"><img src="../assets/brand/app-icon-192.png" alt=""><span>EMPRENDIMIENTOOS</span></div>`;
const title=(h,sub='',back='')=>`${back?`<a class="back" href="#${back}">${icon('chevron-left')}Volver</a>`:brand()}<header class="page-title"><h1>${h}</h1>${sub?`<p class="${back?'help':''}">${sub}</p>`:''}</header>`;
const nav=active=>`<nav class="navigation" aria-label="Navegación principal">${[['hoy','house','Hoy'],['pedidos','clipboard-list','Pedidos'],['recetario','book-open','Recetario'],['mas','ellipsis','Más']].map(([r,i,n])=>`<a href="#${r}" ${active===r?'aria-current="page"':''}>${icon(i)}${n}</a>`).join('')}</nav>`;
const notice=(text,type='')=>`<div class="notice ${type}" ${type==='error'?'role="alert"':''}>${icon(type==='error'?'triangle-alert':type==='success'?'check':'info')}<p>${text}</p></div>`;
const field=(name,label,value,type='text',help='',attrs='')=>`<div class="field" id="field-${name}"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${help?`aria-describedby="help-${name} error-${name}"`:`aria-describedby="error-${name}"`} ${attrs}>${help?`<p class="help" id="help-${name}">${help}</p>`:''}<p class="error-text" id="error-${name}"></p></div>`;
const select=(name,label,opts,value)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${opts.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></div>`;
const currency=(name,label,value)=>`<div class="field" id="field-${name}"><label for="${name}">${label}</label><div class="currency-wrap"><input id="${name}" name="${name}" inputmode="decimal" value="${value}" aria-describedby="error-${name}"><span>MXN</span></div><p class="error-text" id="error-${name}"></p></div>`;
const textarea=(name,label,value)=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" rows="3">${esc(value)}</textarea></div>`;
const kv=(a,b)=>`<div class="kv"><span>${a}</span><span>${b}</span></div>`;
const finish=(text='Guardar',type='submit')=>`<footer class="sticky-save"><button class="button full" type="${type}">${text}</button></footer>`;
function day(){return `<div class="page compact-home">${title('Hoy en tu cocina','Viernes 18 de septiembre')}<section><div class="section-head"><div><h2>Producción de hoy</h2><p>24 piezas por preparar</p></div><img class="food-small" src="../imagery/cinnamon-rolls-master.png" alt="Roles de canela en un plato crema"></div>${[['12','roles de canela','Ana','12:30'],['12','empanadas','Luis','17:00']].map(([n,p,c,t])=>`<a class="row production-row link" href="#produccion"><span class="quantity">${n}</span><div class="row-body"><strong>${p}</strong><span class="meta">${c}</span></div><div class="row-end"><span class="meta">Entrega</span><br><strong>${t}</strong></div>${icon('chevron-right','sm')}</a>`).join('')}</section><section class="section rule"><h2>Entregas de hoy (2)</h2><div style="margin-top:12px">${[['Ana','12:30',48000-amountPaid,'12 roles de canela'],['Luis','17:00',48000-luisPaid,'12 empanadas']].map(([c,t,b,p])=>`<a class="row delivery-row link" href="#cobro" data-customer="${c}"><div class="row-body"><strong>${c} <span style="float:right;font-weight:500">${t}</span></strong><span class="meta">${p}</span></div><div class="row-end">Saldo ${short(b)}</div>${icon('chevron-right','sm')}</a>`).join('')}</div></section><section class="section rule"><h2>Resumen de hoy</h2><div class="summary"><div><span class="help">Por cobrar hoy</span><p class="money">${short(96000-amountPaid-luisPaid)} <small>MXN</small></p></div><div><span class="help">Ganancia estimada</span><p class="money positive">$480 <small>MXN</small></p></div></div></section><div class="actions">${link('Ver producción','produccion','full')}${link('Registrar compra','compra','secondary full','plus')}</div></div>${nav('hoy')}`}
function purchase(){return `<form data-form="purchase" novalidate><div class="page">${title('Registrar compra','Registra lo que compraste y cuánto pagaste.','hoy')}${field('ingredient','Ingrediente','Harina de trigo','text','','required autocomplete="off" list="ingredients-list"')}<datalist id="ingredients-list"><option>Harina de trigo</option><option>Mantequilla</option><option>Azúcar</option></datalist>${field('presentation','Presentación','Bolsa','text','Por ejemplo: bolsa de 1 kg o paquete de 12 piezas.')}<div class="fieldpair">${field('quantity','Cantidad comprada','1','text','Cantidad total de la compra.','inputmode="decimal"')}${select('unit','Unidad',[['kg','kg'],['g','g'],['l','L'],['ml','ml'],['piece','piezas']],'kg')}</div>${currency('total','Total pagado','42.00')}${field('purchase-date','Fecha','2026-09-18','date')}<details><summary>Tienda y nota (opcional)</summary>${field('store','Tienda o proveedor','','text')}${textarea('note','Nota','')}</details><div class="computed" aria-live="polite"><strong>Equivalencias y costo unitario</strong><div class="summary"><div><span class="help">Equivale a</span><p class="money" id="normalized">1,000 g</p></div><div><span class="help" id="unit-cost-label">Costo por gramo</span><p class="money" id="normalized-cost">$0.0420</p></div></div></div><p class="help">Se agrega al historial de compras. Tus pedidos anteriores conservan su costo de referencia.</p><div id="form-message"></div></div>${finish('Guardar compra')}</form>`}
function recipe(){return `<form data-form="recipe" novalidate><div class="page">${title('Receta','Versión 3 · Roles de canela','recetario')}<img class="hero-img" src="../imagery/cinnamon-rolls-master.png" alt="Roles de canela, fotografía de referencia">${field('recipe-name','Nombre de la receta','Roles de canela')}<section><div class="section-head"><h2>Ingredientes</h2>${btn('Agregar','ingredient','tertiary small','plus')}</div><div id="ingredient-rows">${recipeIngredients.map(([n,q,u,c],idx)=>`<div class="row"><div class="row-body"><strong>${n}</strong><span class="help">${q} ${u}</span></div><span>${c}</span><button class="button tertiary icon-only" type="button" data-action="edit-ingredient" data-index="${idx}" aria-label="Editar ${n}">${icon('pencil')}</button></div>`).join('')}</div></section><div class="section">${field('yield','Rendimiento esperado','12','text','Número de piezas que salen de esta receta.','inputmode="numeric"')}</div>${textarea('instructions','Preparación','1. Mezcla y amasa los ingredientes.\n2. Deja reposar, rellena y forma los roles.\n3. Hornea hasta que estén dorados.')}${textarea('recipe-notes','Notas (opcional)','Dejar enfriar antes de empacar.')}<details><summary>Costo de esta receta</summary>${kv('Ingredientes','$80.00')}${kv('Gas y esfuerzo por tanda','$112.00')}${kv('Total de la tanda','$192.00')}${kv('Costo por pieza de receta','$16.00')}<p class="help">El empaque y los costos por pedido se agregan en el producto.</p></details>${notice('Guardar cambios crea una nueva versión. Los pedidos anteriores conservan su receta y costo.')}<div id="form-message"></div></div>${finish('Guardar receta')}</form>`}
const scenarios={'2':{price:4000,gain:2000,batch:24000,margin:'50.0%'},'2.5':{price:5000,gain:3000,batch:36000,margin:'60.0%'},'3':{price:6000,gain:4000,batch:48000,margin:'66.7%'},'3.5':{price:7000,gain:5000,batch:60000,margin:'71.4%'}};
function product(){const s=scenarios[factor];return `<div class="page">${title('Costos y precio','Roles de canela · Por pieza','recetario')}<section class="card"><span class="help">Costo por pieza</span><p class="money">$20.00 <small>MXN</small></p><div class="summary"><div><span class="help">Precio actual</span><p class="money">${money(currentPrice)}</p></div><div><span class="help">Ganancia por pieza</span><p class="money ${currentPrice>=2000?'positive':'negative'}">${money(currentPrice-2000)}</p></div></div><p class="help" style="margin-top:12px">Margen: ${((currentPrice-2000)/currentPrice*100).toFixed(1)}% del precio de venta.</p></section><details><summary>Ver desglose del costo</summary>${kv('Receta: $192 ÷ 12 piezas','$16.00')}${kv('Empaque por pieza','$2.00')}${kv('Entrega: $24 ÷ 12 piezas','$2.00')}${kv('Costo atribuible por pieza','$20.00')}<p class="help">La entrega se reparte entre las 12 piezas de este pedido de referencia. En otro pedido puede cambiar.</p></details><section class="section"><h2>Explora otro precio</h2><p class="help">Multiplica el costo. Esto no cambia tu precio actual.</p><div class="segments" aria-label="Multiplicador del costo">${['2','2.5','3','3.5'].map(f=>`<button data-factor="${f}" aria-pressed="${factor===f}">×${f}</button>`).join('')}</div><div class="computed"><span class="help">Precio sugerido con ×${factor}</span><p class="money">${money(s.price)} <small>MXN</small></p>${kv('Ganancia por pieza',money(s.gain))}${kv('Ganancia de 12 piezas',money(s.batch))}${kv('Margen sobre venta',s.margin)}</div>${btn('Usar este precio','price','full')}</section><details><summary>Costos adicionales</summary><p class="help">Cada costo se asigna una sola vez.</p>${kv('Por tanda','Gas y esfuerzo · $112')}${kv('Por pieza','Empaque · $2')}${kv('Por pedido / entrega','Entrega · $24')}${btn('Editar costos','costs','secondary full')}</details><div class="field">${field('current-price','Precio de venta manual','40.00','text','','inputmode="decimal"')}</div>${btn('Guardar precio manual','manual-price','secondary full')}<div class="row"><div class="row-body"><strong>Producto activo</strong><span class="help">Disponible para nuevos pedidos</span></div><input type="checkbox" checked role="switch" aria-label="Producto activo" id="product-active" style="width:48px;height:48px"></div><a class="row link" href="#historial">${icon('history')}Ver cómo ha cambiado${icon('chevron-right')}</a></div>`}
let orderQuantity=12;
function order(){return `<form data-form="order" novalidate><div class="page">${title('Tomar pedido','Los detalles de tu próxima entrega.','pedidos')}${field('client','Cliente','Ana','text','Elige un nombre o escribe uno nuevo.','list="clients"')}<datalist id="clients"><option>Ana</option><option>Luis</option></datalist><section><div class="section-head"><h2>Productos</h2>${btn('Agregar','add-product','tertiary small','plus')}</div><div class="row"><div class="row-body"><strong>Roles de canela</strong><span class="help">$40.00 por pieza</span></div></div><div class="row"><div class="row-body">Cantidad</div><div class="stepper">${btn('','less','icon-only','minus')}<output id="order-quantity" aria-label="Piezas de roles">${orderQuantity}</output>${btn('','more','icon-only','plus')}</div></div><div id="extra-product"></div></section><div class="section fieldpair equal">${field('delivery-date','Fecha de entrega','2026-09-18','date')}${field('delivery-time','Hora','12:30','time')}</div>${textarea('order-note','Nota (opcional)','Sin nuez.')}${currency('advance','Anticipo recibido','240.00')}<div class="computed"><div class="kv"><strong>Total del pedido</strong><strong id="order-total">${money(orderQuantity*4000)}</strong></div>${kv('Anticipo','<span id="advance-display">$240.00</span>')}${kv('Saldo pendiente','<strong id="balance-display">'+money(orderQuantity*4000-24000)+'</strong>')}<p class="help">MXN · El precio acordado se conserva en este pedido.</p></div><div id="form-message"></div></div>${finish('Guardar pedido')}</form>`}
function collection(){let ana=customer==='Ana', paid=ana?amountPaid:luisPaid, balance=48000-paid;return `<div class="page">${title(customer,'Pedido #'+(ana?'018':'019')+' · Hoy, '+(ana?'12:30':'17:00'),'pedidos')}<div class="chips"><span class="chip">${(ana?delivered:luisDelivered)?'Entregado':'Listo para entregar'}</span><span class="chip ${balance?'pending':''}">${balance?'Pago parcial':'Pagado'}</span></div><div class="section"><div class="row"><div class="row-body"><strong>12 ${ana?'roles de canela':'empanadas'}</strong><span class="help">$40.00 por pieza</span></div><strong>$480.00</strong></div></div><section class="computed"><span class="help">Saldo pendiente</span><p class="money">${money(balance)} <small>MXN</small></p>${kv('Total del pedido','$480.00')}${kv('Ya recibiste',money(paid))}</section><div class="actions">${balance>0?btn('Registrar cobro','payment','full','wallet'):'<button class="button full" disabled>Pedido pagado</button>'}${btn((ana?delivered:luisDelivered)?'Entrega registrada':'Marcar como entregado','deliver','secondary full','truck')}</div><p class="help" style="margin-top:12px">Entregar no cambia el pago. Cobrar no cambia la entrega.</p><details><summary>Pagos registrados</summary>${kv('Anticipo · 17 sep 2026',ana?'$240.00':'$80.00')}${paid>(ana?24000:8000)?kv('Cobro · 18 sep 2026',money(paid-(ana?24000:8000))):''}</details><details><summary>Notas del pedido</summary><p>${ana?'Sin nuez.':'Entregar en caja.'}</p></details>${btn('Cancelar pedido','cancel-order','tertiary full')}</div>`}
function production(){if(drafts.produccion?.['production-date'] && drafts.produccion['production-date']!=='2026-09-18')return `<div class="page">${title('Producción','Prepara lo necesario para tus entregas.','hoy')}${field('production-date','Fecha',drafts.produccion['production-date'],'date')}<div class="empty">${icon('cooking-pot')}<h2>No hay pedidos para esta fecha</h2><p>Elige otra fecha o registra un pedido.</p>${link('Tomar pedido','pedido','full')}</div></div>`;return `<div class="page">${title('Producción','Prepara lo necesario para tus entregas.','hoy')}${field('production-date','Fecha','2026-09-18','date')}<div class="computed"><span class="help">Necesitas preparar</span><p class="money">24 piezas</p><span class="help">2 pedidos para esta fecha</span></div><section><div class="row"><span class="quantity">12</span><div class="row-body"><strong>Roles de canela</strong><span class="help">Ana · Entrega 12:30</span></div>${btn('Ver','production-detail','tertiary small')}</div><div class="row"><span class="quantity">12</span><div class="row-body"><strong>Empanadas</strong><span class="help">Luis · Entrega 17:00</span></div>${btn('Ver','production-detail','tertiary small')}</div></section><section class="section rule"><h2>Estimación de esta producción</h2>${kv('Venta acordada','$960.00')}${kv('Costo atribuible estimado','$480.00')}${kv('Ganancia estimada','<strong class="positive">$480.00</strong>')}<p class="help">MXN · Se usa el costo de referencia de cada pedido. Los anticipos no cambian esta ganancia.</p></section>${productionStarted?'<div class="notice success" role="status">En preparación · 2 pedidos</div>':btn('Iniciar preparación','start-production','full section')}${notice('Revisa las notas de cada pedido antes de preparar.')}</div>`}
function history(){return `<div class="page">${title('Antes y ahora','Roles de canela · Costo por pieza','mas')}<div class="fieldpair equal">${field('asof','Comparar con','2026-08-18','date')}${field('current-date','Hasta','2026-09-18','date')}</div>${btn('Comparar fechas','compare','secondary full','history')}<div id="history-body"><section class="section"><h2>Tu costo subió $2.00</h2><p class="help">De $18.00 a $20.00 por pieza · +11.1%</p><div class="card section"><div class="summary"><div><span class="help">18 ago 2026</span><p class="money">$18.00</p></div><div><span class="help">18 sep 2026</span><p class="money">$20.00</p></div></div></div></section><section class="section rule"><h2>El precio se mantuvo</h2>${kv('Precio antes / ahora','$40.00 / $40.00')}${kv('Ganancia por pieza','$22.00 → $20.00')}${kv('Margen sobre venta','55.0% → 50.0%')}</section><section class="section rule"><h2>¿Qué cambió?</h2><div class="row"><div class="row-body"><strong>Mantequilla</strong><span class="help">Aumento por pieza</span></div><strong>+$1.50</strong></div><div class="row"><div class="row-body"><strong>Harina de trigo</strong><span class="help">Aumento por pieza</span></div><strong>+$0.50</strong></div><p class="help">Misma receta y rendimiento: 12 piezas. Costos adicionales sin cambios.</p></section><details><summary>Origen de esta comparación</summary><p>Registros económicos vigentes al cierre de cada fecha, en la zona horaria del negocio. El costo actual usa la última compra registrada. Los pedidos históricos conservan su propia referencia.</p></details></div>${link('Explorar otro precio','producto','full section')}</div>`}
function orders(){return `<div class="page">${title('Pedidos','Lo que preparas, entregas y cobras.')}<div class="field"><label for="search-orders">Buscar cliente</label><input id="search-orders" type="search" placeholder="Nombre del cliente"></div><div class="tabs" role="tablist" aria-label="Estado de pedidos"><button role="tab" aria-selected="true" data-filter="today">Hoy</button><button role="tab" aria-selected="false" data-filter="due">Por cobrar</button><button role="tab" aria-selected="false" data-filter="all">Todos</button></div><div id="orders-list">${['Ana','Luis'].map((c,i)=>`<a href="#cobro" data-customer="${c}" class="row link" data-order-name="${c.toLowerCase()}"><div class="row-body"><strong>${c} · ${i?'17:00':'12:30'}</strong><span class="help">12 ${i?'empanadas':'roles de canela'}</span><div class="chips" style="margin-top:8px"><span class="chip pending">Pago parcial</span></div></div><span>Saldo ${i?'$400':'$240'}</span>${icon('chevron-right','sm')}</a>`).join('')}</div><p id="search-empty" class="help" hidden>No hay pedidos con ese nombre.</p><div class="actions">${link('Tomar pedido','pedido','full','plus')}</div></div>${nav('pedidos')}`}
function recipeHub(){return `<div class="page">${title('Recetario','Tus recetas y lo que vendes.')}<div class="tabs" role="tablist" aria-label="Recetario"><button role="tab" aria-selected="true" data-catalog="recipes">Recetas</button><button role="tab" aria-selected="false" data-catalog="products">Productos</button></div><a id="catalog-row" href="#receta" class="row link"><img src="../imagery/cinnamon-rolls-master.png" class="food-small" alt=""><div class="row-body"><strong>Roles de canela</strong><span class="help">Rinde 12 piezas</span></div>${icon('chevron-right')}</a><div class="section">${link('Ver costos y precio','producto','secondary full','calculator')}</div></div>${nav('recetario')}`}
function more(){return `<div class="page">${title('Más','Todo lo que sostiene tu cocina.')}${[['ingredientes','wheat','Ingredientes','Compras y costo actual'],['compra','shopping-bag','Registrar compra','Agrega una compra al historial'],['historial','history','Historial','Compara tus costos y precios']].map(([r,i,h,s])=>`<a class="row link" href="#${r}">${icon(i)}<div class="row-body"><strong>${h}</strong><span class="help">${s}</span></div>${icon('chevron-right')}</a>`).join('')}</div>${nav('mas')}`}
function ingredients(){return `<div class="page">${title('Ingredientes','Costo de la última compra registrada.','mas')}<div class="row"><div class="row-body"><strong>Harina de trigo</strong><span class="help">Última compra: 18 sep 2026</span></div><span>$0.0420/g</span></div><details open><summary>Historial de compras</summary>${kv('18 sep · 1kg · Bolsa','$42.00')}${kv('18 ago · 1kg · Bolsa','$30.00')}<p class="help">Cada compra es un registro. No se muestra inventario.</p></details>${link('Registrar compra','compra','full','plus')}</div>`}
const routes={hoy:day,compra:purchase,receta:recipe,producto:product,pedido:order,cobro:collection,produccion:production,historial:history,pedidos:orders,recetario:recipeHub,mas:more,ingredientes:ingredients};
let current='hoy';
function captureDraft(){if(!app)return;const data={};app.querySelectorAll('input[name],select[name],textarea[name]').forEach(e=>data[e.name]=e.value);drafts[current]=data}
function applyDraft(){for(const [name,value] of Object.entries(drafts[current]||{})){const e=document.getElementsByName(name)[0];if(e)e.value=value}}
function render(){current=location.hash.slice(1)||'hoy'; if(!routes[current])current='hoy';app.innerHTML=routes[current]();applyDraft();document.title=app.querySelector('h1')?.textContent+' · EmprendimientoOS';if(viewState!=='default')renderState();if(current==='compra')updatePurchase();if(current==='receta')updateRecipeCosts();if(current==='pedido')updateOrder();app.querySelector('[data-action=less]')?.setAttribute('aria-label','Quitar una pieza');app.querySelector('[data-action=more]')?.setAttribute('aria-label','Agregar una pieza');}
function renderState(){const page=app.querySelector('.page');if(viewState==='loading'){page.innerHTML=title('Cargando…','','hoy')+'<div role="status" aria-live="polite"><p class="help">Estamos consultando tus datos.</p><div aria-hidden="true"><div class="skeleton big"></div><div class="skeleton"></div><div class="skeleton"></div></div></div>';app.querySelector('.sticky-save')?.remove()}else if(viewState==='empty'){page.innerHTML=title('Todavía no hay registros','','hoy')+`<div class="empty">${icon('book-open')}<h2>Empieza con lo que ya sabes</h2><p>Registra una compra para conocer el costo de tus ingredientes.</p>${link('Registrar compra','compra','full','plus')}</div>`;app.querySelector('.sticky-save')?.remove()}else{page.insertAdjacentHTML('afterbegin',notice('No pudimos cargar la información. Revisa tu conexión e intenta de nuevo.','error')+btn('Reintentar','retry','secondary full'));}}
function toast(text){const t=document.querySelector('#toast');clearTimeout(toastTimer);t.textContent=text;t.hidden=false;toastTimer=setTimeout(()=>t.hidden=true,6000)}
function openSheet(h,body){sheet.innerHTML=`<div class="dialog-body"><div class="dialog-head"><h2 id="dialog-title">${h}</h2><button class="button tertiary icon-only" data-action="close" aria-label="Cerrar">${icon('x')}</button></div>${body}</div>`;sheet.showModal()}
function error(name,text){const e=document.querySelector('#'+name);e?.setAttribute('aria-invalid','true');document.querySelector('#field-'+name)?.classList.add('invalid');const message=document.querySelector('#error-'+name);if(message)message.textContent=text;return false}
function clearErrors(){app.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));app.querySelectorAll('.invalid').forEach(e=>e.classList.remove('invalid'));app.querySelectorAll('.error-text').forEach(e=>e.textContent='')}
function cents(v){let s=String(v).trim().replace(/^\$/,'');if(!/^\d+(?:[.,]\d{1,2})?$/.test(s))return null;let [a,b='']=s.replace(',','.').split('.');return Number(a)*100+Number(b.padEnd(2,'0'))}
function decimal(v){const s=String(v).trim().replace(',','.');return /^\d+(\.\d{1,3})?$/.test(s)?Number(s):NaN}
function updatePurchase(){const q=document.querySelector('#quantity'),total=document.querySelector('#total');if(!q||!total)return;const unit=document.querySelector('#unit').value,n=decimal(q.value)*(unit==='kg'||unit==='l'?1000:1),cost=cents(total.value),out=document.querySelector('#normalized'),price=document.querySelector('#normalized-cost');const u=['kg','g'].includes(unit)?'g':['l','ml'].includes(unit)?'ml':'piezas';out.textContent=n>0?new Intl.NumberFormat('es-MX',{maximumFractionDigits:3}).format(n)+' '+u:'—';document.querySelector('#unit-cost-label').textContent=u==='g'?'Costo por gramo':u==='ml'?'Costo por mililitro':'Costo por pieza';price.textContent=n>0&&cost>0?'$'+(cost/100/n).toFixed(4):'—'}
function updateRecipeCosts(){const detail=[...app.querySelectorAll('details')].find(e=>e.querySelector('summary')?.textContent==='Costo de esta receta');if(!detail)return;const y=Number(document.querySelector('#yield')?.value);const known=recipeIngredients.every(r=>r[3]!=='Por recalcular');detail.innerHTML='<summary>Costo de esta receta</summary>'+(known&&y>0?kv('Ingredientes','$80.00')+kv('Gas y esfuerzo por tanda','$112.00')+kv('Total de la tanda','$192.00')+kv('Costo por pieza de receta',money(19200/y))+'<p class="help">El empaque y los costos por pedido se agregan en el producto.</p>':notice('El costo está pendiente de recalcular. No se presenta un total como si estuviera completo.','warning'))}
function updateOrder(){const e=document.querySelector('#advance');if(!e)return;const a=cents(e.value)||0;document.querySelector('#order-total').textContent=money(orderQuantity*4000);document.querySelector('#advance-display').textContent=money(a);document.querySelector('#balance-display').textContent=money(orderQuantity*4000-a)}
document.addEventListener('input',e=>{if(e.target.closest('#app')){captureDraft();if(current==='compra')updatePurchase();if(current==='receta')updateRecipeCosts();if(current==='pedido')updateOrder();app.querySelector('[data-action=less]')?.setAttribute('aria-label','Quitar una pieza');app.querySelector('[data-action=more]')?.setAttribute('aria-label','Agregar una pieza');}if(e.target.id==='search-orders'){let n=0;document.querySelectorAll('[data-order-name]').forEach(row=>{row.hidden=!row.dataset.orderName.includes(e.target.value.toLowerCase());if(!row.hidden)n++});document.querySelector('#search-empty').hidden=n>0}});
document.addEventListener('change',e=>{if(e.target.id==='production-date'){captureDraft();render()}if(e.target.id==='unit')updatePurchase();if(e.target.id==='state-picker'){viewState=e.target.value;render()}if(e.target.id==='product-active')toast(e.target.checked?'Producto disponible para nuevos pedidos.':'Producto inactivo; su historial se conserva.')});
document.addEventListener('click',e=>{const linkEl=e.target.closest('a[href^="#"]');if(linkEl){captureDraft();if(linkEl.dataset.customer)customer=linkEl.dataset.customer;if(linkEl.dataset.action==='pick-product'){sheet.close();orderQuantity++;if(current==='pedido'){document.querySelector('#order-quantity').textContent=orderQuantity;updateOrder()}}if(viewState==='empty')viewState='default'}const b=e.target.closest('button');if(!b)return;if(b.dataset.factor){factor=b.dataset.factor;captureDraft();render();return}if(b.dataset.catalog){document.querySelectorAll('[data-catalog]').forEach(x=>x.setAttribute('aria-selected',x===b));document.querySelector('#catalog-row').href=b.dataset.catalog==='products'?'#producto':'#receta';return}if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-selected',x===b));toast('Los dos pedidos de ejemplo coinciden con este filtro.');return}const a=b.dataset.action;if(!a)return;
if(a==='close'){sheet.close();return}if(a==='retry'){viewState='default';document.querySelector('#state-picker').value='default';render();return}
if(a==='more'||a==='less'){orderQuantity=Math.max(1,orderQuantity+(a==='more'?1:-1));document.querySelector('#order-quantity').textContent=orderQuantity;updateOrder();return}
if(a==='ingredient'||a==='edit-ingredient'){captureDraft();selectedIngredient=a==='ingredient'?-1:Number(b.dataset.index);const row=recipeIngredients[selectedIngredient]||['','','g','—'];openSheet('Ingrediente de la receta',field('ingredient-edit','Ingrediente',row[0])+field('ingredient-quantity','Cantidad',row[1],'text','','inputmode="decimal"')+select('ingredient-unit','Unidad',[['g','g'],['ml','ml'],['piece','piezas']],row[2])+btn('Aplicar a la receta','apply-ingredient','full'));return}
if(a==='apply-ingredient'){const qty=decimal(document.querySelector('#ingredient-quantity').value);if(!(qty>0)){document.querySelector('#ingredient-quantity').setCustomValidity('Escribe una cantidad mayor que cero.');document.querySelector('#ingredient-quantity').reportValidity();return}const row=[document.querySelector('#ingredient-edit').value,String(qty),document.querySelector('#ingredient-unit').value,'Por recalcular'];if(selectedIngredient<0)recipeIngredients.push(row);else recipeIngredients[selectedIngredient]=row;sheet.close();render();toast('Ingrediente aplicado al borrador. Revisa el costo antes de guardar.');return}
if(a==='add-product'){openSheet('Agregar producto',`<a class="row link" href="#pedido" data-action="pick-product">${icon('package')}Roles de canela · $40.00</a>`+notice('El caso de referencia utiliza un producto. El contrato describe pedidos con varias líneas.'));return}
if(a==='price'||a==='manual-price'){const val=a==='price'?scenarios[factor].price:cents(document.querySelector('#current-price').value);if(!(val>0)){error('current-price','Escribe un precio mayor que $0.');return}pendingPrice=val;openSheet('Cambiar precio',`<p>El nuevo precio será <strong>${money(val)} MXN</strong>. Se aplicará a nuevos pedidos.</p>`+notice('Los pedidos anteriores conservan su precio acordado.')+`<div class="actions">${btn('Confirmar precio','confirm-price','full')}${btn('Volver','close','secondary full')}</div>`);return}
if(a==='confirm-price'){currentPrice=pendingPrice;sheet.close();render();toast('Precio actualizado en el ejemplo; los pedidos conservan su precio.');return}
if(a==='costs'){openSheet('Costo adicional',field('cost-name','Concepto','Empaque')+currency('cost-amount','Importe','2.00')+select('allocation','Aplicar',[['unit','Por pieza'],['batch','Por tanda'],['order','Por pedido / entrega']],'unit')+btn('Aplicar al borrador','apply-cost','full'));return}
if(a==='apply-cost'){sheet.close();toast('Costo aplicado al borrador de referencia.');return}
if(a==='payment'){const balance=customer==='Ana'?48000-amountPaid:48000-luisPaid;if(balance===0){toast('El pedido está pagado. No hay saldo pendiente.');return}openSheet('Registrar cobro',`<p style="margin-bottom:16px">${customer} · Saldo ${money(balance)} MXN</p>`+currency('payment','Importe recibido',(balance/100).toFixed(2))+field('payment-date','Fecha del cobro','2026-09-18','date')+btn('Confirmar cobro','confirm-payment','full'));return}
if(a==='confirm-payment'){const v=cents(document.querySelector('#payment').value),balance=customer==='Ana'?48000-amountPaid:48000-luisPaid;if(!(v>0)||v>balance){const f=document.querySelector('#payment');f.setCustomValidity('Escribe un importe mayor que $0 y no mayor que el saldo.');f.reportValidity();return}if(customer==='Ana')amountPaid+=v;else luisPaid+=v;sheet.close();render();toast('Cobro registrado en el ejemplo.');return}
if(a==='deliver'){if(customer==='Ana'?delivered:luisDelivered){toast('La entrega ya está registrada.');return}openSheet('Confirmar entrega',`<p>¿Entregaste las 12 piezas a ${customer}?</p>`+notice('El saldo pendiente se conserva hasta registrar el cobro.')+`<div class="actions">${btn('Sí, ya entregué','confirm-delivery','full')}${btn('Todavía no','close','secondary full')}</div>`);return}
if(a==='confirm-delivery'){if(customer==='Ana')delivered=true;else luisDelivered=true;sheet.close();render();toast('Entrega registrada en el ejemplo.');return}
if(a==='cancel-order'){openSheet('Cancelar pedido',`<p>Se retirará de la producción pendiente. Sus pagos e historial se conservarán.</p>`+notice('Este pedido tiene un anticipo. Cancelarlo no registra una devolución.','warning')+`<div class="actions">${btn('Conservar pedido','close','secondary full')}${btn('Confirmar cancelación','confirm-cancel','danger full')}</div>`);return}
if(a==='confirm-cancel'){sheet.close();toast('Cancelación mostrada. Esta referencia no modifica pedidos reales.');return}
if(a==='production-detail'){const who=b.closest('.row').textContent.includes('Luis')?'Luis':'Ana';openSheet('Pedidos de esta producción',`<p>12 piezas · Un pedido de referencia</p><a class="row link" href="#cobro" data-customer="${who}">${who} · Entrega ${who==='Ana'?'12:30':'17:00'} ${icon('chevron-right')}</a>`);return}
if(a==='start-production'){openSheet('Iniciar preparación',`<p>Se marcarán los dos pedidos como En preparación. No se registrará entrega ni pago.</p><div class="actions">${btn('Iniciar','confirm-start','full')}${btn('Volver','close','secondary full')}</div>`);return}
if(a==='confirm-start'){productionStarted=true;sheet.close();render();toast('En preparación · 2 pedidos de ejemplo.');return}
if(a==='compare'){const date=document.querySelector('#asof').value,end=document.querySelector('#current-date').value;if(end<date){document.querySelector('#history-body').innerHTML=notice('La fecha final debe ser igual o posterior a la inicial.','error');return}if(date!=='2026-08-18'||end!=='2026-09-18'){document.querySelector('#history-body').innerHTML=notice('No hay una referencia económica para esa fecha. Elige 18 ago 2026 para ver el ejemplo.','warning')}else render();}
});
app.addEventListener('submit',e=>{e.preventDefault();clearErrors();captureDraft();let valid=true;const kind=e.target.dataset.form;if(kind==='purchase'){if(!document.querySelector('#ingredient').value.trim())valid=error('ingredient','Escribe el nombre del ingrediente.');if(!document.querySelector('#presentation').value.trim())valid=error('presentation','Describe la presentación comprada.');if(!(decimal(document.querySelector('#quantity').value)>0))valid=error('quantity','Escribe una cantidad mayor que cero.');if(!(cents(document.querySelector('#total').value)>0))valid=error('total','Escribe un total mayor que $0.');if(!document.querySelector('#purchase-date').value)valid=error('purchase-date','Elige la fecha de la compra.')}if(kind==='recipe'){if(!document.querySelector('#recipe-name').value.trim())valid=error('recipe-name','Escribe el nombre de la receta.');if(!/^[1-9]\d*$/.test(document.querySelector('#yield').value))valid=error('yield','Escribe un número entero mayor que cero.')}if(kind==='order'){if(!document.querySelector('#client').value.trim())valid=error('client','Escribe el nombre del cliente.');let a=cents(document.querySelector('#advance').value);if(a===null||a>orderQuantity*4000)valid=error('advance','El anticipo debe estar entre $0 y el total.');if(!document.querySelector('#delivery-date').value)valid=error('delivery-date','Elige la fecha de entrega.');if(!document.querySelector('#delivery-time').value)valid=error('delivery-time','Elige la hora de entrega.')}if(!valid){app.querySelector('[aria-invalid]')?.focus();return}const b=e.submitter;b.disabled=true;b.setAttribute('aria-busy','true');const previous=b.textContent;b.innerHTML=icon('loader-circle','spinner')+'Guardando…';setTimeout(()=>{b.disabled=false;b.removeAttribute('aria-busy');b.textContent=previous;document.querySelector('#form-message').innerHTML=notice(kind==='purchase'?'Compra registrada en el ejemplo. Tus datos permanecen visibles.':kind==='recipe'?'Nueva versión de receta mostrada en el ejemplo.':'Pedido registrado en el ejemplo.','success');toast('Demostración completada. No se guardaron datos reales.');},650)});
window.addEventListener('hashchange',()=>{document.querySelector('#toast').hidden=true;if(sheet.open)sheet.close();render();window.scrollTo(0,0)});document.querySelector('#state-picker').value=viewState;render();
